SELECT o.tableoid::pg_catalog.oid::pg_catalog.text AS catalog_class_oid, o.oid::pg_catalog.text AS object_oid, o.opfnamespace::pg_catalog.text AS namespace_oid, pg_catalog.to_jsonb(o)::pg_catalog.text AS original_catalog_row_json FROM pg_catalog.pg_opfamily o WHERE o.oid = ANY($1::pg_catalog.oid[]) ORDER BY o.oid